import React from "react";
import { User, Edit3, LogOut, Trophy, Award, Zap, Flame, BookOpen } from "lucide-react";
import { useNavigate } from "react-router-dom";
import "../App.css";

export default function Profile({ user }) {
  const navigate = useNavigate();

  // Fallback data if user is null (though App.js usually prevents access)
  const userName = user?.name || "Student";
  const userEmail = user?.email || "student@vidyaquest.edu";
  const userGrade = user?.grade || "10";

  return (
    <div className="dashboard-container">
      {/* 1. PROFILE HEADER CARD (Green Banner) */}
      <div className="profile-banner-card">
        <div className="banner-top"></div>
        
        <div className="banner-content">
          <div className="profile-avatar">
             <User size={50} strokeWidth={2} />
          </div>
          
          <div className="profile-text">
             {/* DYNAMIC NAME HERE */}
             <h1>{userName}</h1>
             <p>Grade {userGrade} • {userEmail}</p>
          </div>

          <div className="banner-actions">
             <button className="btn-secondary" style={{display:'flex', alignItems:'center', gap:'5px'}}>
                <Edit3 size={16}/> Edit Profile
             </button>
             <button 
                className="btn-secondary" 
                style={{color:'#ef4444', borderColor:'#fca5a5', display:'flex', alignItems:'center', gap:'5px'}} 
                onClick={() => navigate("/")} // Simple redirect, App.js handles state cleanup on logout usually
             >
                <LogOut size={16}/> Sign Out
             </button>
          </div>
        </div>
      </div>

      {/* 2. MIDDLE SECTION: Progress & Badges */}
      <div className="dash-grid">
         {/* Level Progress */}
         <div className="dash-card">
            <h3 style={{margin:'0 0 1.5rem', display:'flex', gap:'10px', alignItems:'center', color:'#1e293b'}}>
               <Trophy size={20} color="#10b981"/> Level Progress
            </h3>
            <div style={{display:'flex', gap:'1rem', alignItems:'center'}}>
               <div style={{background:'#10b981', width:'70px', height:'70px', borderRadius:'16px', display:'flex', alignItems:'center', justifyContent:'center', color:'white', fontSize:'2rem', fontWeight:'800'}}>
                  1
               </div>
               <div style={{flex:1}}>
                  <div className="level-info"><span>Level 1</span><span style={{color:'#64748b'}}>402 / 500 XP</span></div>
                  <div className="progress-bg">
                     <div className="progress-fill" style={{width: '80%'}}></div>
                  </div>
                  <div style={{fontSize:'0.9rem', color:'#64748b', marginTop:'8px', fontWeight:'500'}}>98 XP until Level 2</div>
               </div>
            </div>
         </div>

         {/* Badges */}
         <div className="dash-card" style={{textAlign:'center', display:'flex', flexDirection:'column', justifyContent:'center'}}>
            <h3 style={{margin:0, textAlign:'left', width:'100%', display:'flex', gap:'10px', alignItems:'center', color:'#1e293b'}}>
               <Award size={20} color="#10b981"/> Badges
            </h3>
            <div style={{marginTop:'1.5rem', color:'#94a3b8'}}>
               <Award size={48} style={{opacity:0.4, marginBottom:'10px'}}/>
               <p style={{margin:0, fontWeight:'500'}}>Complete quizzes to earn badges!</p>
            </div>
         </div>
      </div>

      {/* 3. BOTTOM STATS */}
      <div className="stats-grid">
         <StatBox icon={<Zap/>} val="402" label="Total XP" color="#dcfce7" />
         <StatBox icon={<Flame/>} val="0" label="Day Streak" color="#ffedd5" />
         <StatBox icon={<BookOpen/>} val="9" label="Quizzes Done" color="#dbeafe" />
         <StatBox icon={<Award/>} val="76%" label="Avg Score" color="#f3e8ff" />
      </div>
    </div>
  );
}

// Helper component for stat boxes
function StatBox({icon, val, label, color}) {
  return (
    <div className="stat-box">
       <div className="stat-icon" style={{background: color, width: '50px', height: '50px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center'}}>
          {React.cloneElement(icon, { size: 24, color: '#333' })} {/* Simplified color for icon */}
       </div>
       <div>
          <h2 style={{margin:'0 0 5px', fontSize:'2rem', color:'#1e293b'}}>{val}</h2>
          <span style={{color:'#64748b', fontWeight:'600', fontSize:'0.9rem'}}>{label}</span>
       </div>
    </div>
  );
}
